// SALIDA DE PERSONA, paso 1: ¿este toque es para este flujo?
//
// El flujo atiende UN numero (se instala por alias: la misma plantilla con otro
// `phoneNumberId` en `Config base`). Dos disparadores llegan aqui: el
// timbre de la Function (POST sin datos) y el barrido de cada minuto, que
// reclama igual por si un timbre se perdio.
//
// - Sin `phoneNumberId` configurado el flujo NO corre: un error visible en la
//   ejecucion, nunca un reclamo con un numero de marcador.
// - Un timbre que trae `X-NovuChat-Numero` de OTRO numero se descarta: la ruta
//   del webhook ya es de este numero, esto es solo un cinturon.
// - La clave y la firma del timbre las verifica el Header Auth del webhook; este
//   nodo no tiene `crypto` y no las toca.
const cfg = $('Config base').first().json;
const numero = String(cfg.phoneNumberId ?? '').trim();
if (!/^[0-9]{8,20}$/.test(numero)) {
  throw new Error('Salida de persona: Config base no tiene el phoneNumberId de este flujo.');
}

const timbre = $('Timbre');
let origen = 'barrido';
if (timbre.isExecuted) {
  origen = 'timbre';
  const cabeceras = (timbre.first().json.headers) || {};
  const deQuien = String(cabeceras['x-novuchat-numero'] ?? '').trim();
  if (deQuien && deQuien !== numero) return [];
}

return [{ json: { origen, phoneNumberId: numero } }];

// SALIDA DE PERSONA, paso 3: de la lista reclamada a un envio por mensaje.
//
// Entra la respuesta de `reclamarSalidaPersona`: { mensajes: [...] } con hasta 10
// mensajes ya pasados a `enviando`. Sale UN item por mensaje con lo que los nodos
// de envio necesitan. Lista vacia = fin del bucle (no sale ningun item).
//
// Un mensaje que NO se puede enviar por un defecto propio (canal que no es
// 'rele' ni 'graph', texto vacio, direccion invalida, rele sin configurar) lleva
// `sinEnvio` con un codigo: el Switch lo manda directo a `Resultado del envío`,
// que lo confirma como rechazado. Nunca se queda en `enviando` ni se envia a ciegas.
const cfg = $('Config base').first().json;
const entrada = $input.all()[0];
const lista = entrada && entrada.json && Array.isArray(entrada.json.mensajes) ? entrada.json.mensajes : [];
const releBase = String(cfg.releBaseUrl ?? '').trim();
const releListo = /^http:\/\/[A-Za-z0-9._-]+(:[0-9]{2,5})?$/.test(releBase);

// ADJUNTOS (B3): un mensaje con `tipo` image|audio|document se planifica aparte. Se valida la
// FORMA del reclamo (el servidor ya la valida; esto es el cinturon) y sale con `ruta: 'adjunto'`
// y `cuerpoAdjunto` SIN el id de Meta: el id lo pone `Preparar envío del adjunto` tras la subida.
// NUNCA hay `link`: el medio se sube a Meta con `/media` y se envia por `id`.
const MIMES = {
  image: { 'image/jpeg': 'jpg', 'image/png': 'png' },
  audio: { 'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac' },
  document: {
    'application/pdf': 'pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
    'text/plain': 'txt',
  },
};
const TOPES = { image: 5 * 1024 * 1024, audio: 16 * 1024 * 1024, document: 16 * 1024 * 1024 };
// Lo MISMO que el servidor quita del nombre al guardarlo (`sanearNombre`): controles y marcas
// invisibles o bidireccionales, mas las barras. Un nombre que el servidor acepto nunca se rechaza aqui.
const NOMBRE_MALO = /[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff\ufff9-\ufffb/\\]/;
let adjuntosEnLote = 0;

function planAdjunto(p, tipo, mensajeId, conversacionId, to, canal, claveRele, texto) {
  const a = p.adjunto;
  let sinEnvio = '';
  let reintentable = false;
  if (!mensajeId || !conversacionId) sinEnvio = 'NV-RECLAMO';
  else if (!Object.prototype.hasOwnProperty.call(MIMES, tipo)) sinEnvio = 'NV-TIPO';
  else if (canal !== 'graph') sinEnvio = 'NV-ADJUNTO-CANAL';
  else if (!/^[0-9]{8,15}$/.test(to)) sinEnvio = 'NV-DESTINO';
  else {
    let forma = false;
    if (a === null || typeof a !== 'object' || Array.isArray(a)) forma = true;
    else if (typeof a.mime !== 'string' || !Object.prototype.hasOwnProperty.call(MIMES[tipo], a.mime)) forma = true;
    else if (texto !== '') forma = true;
    else if (!Number.isInteger(a.tamano) || a.tamano < 1 || a.tamano > TOPES[tipo]) forma = true;
    else if (typeof a.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(a.sha256)) forma = true;
    else if (typeof a.voz !== 'boolean' || (a.voz === true && a.mime !== 'audio/ogg')) forma = true;
    else if (a.leyenda !== undefined && (typeof a.leyenda !== 'string' || tipo === 'audio' || a.leyenda.trim() === '' || a.leyenda.length > 1000)) forma = true;
    else if (a.nombre !== undefined && (typeof a.nombre !== 'string' || tipo !== 'document' || a.nombre.length < 1 || [...a.nombre].length > 240 || NOMBRE_MALO.test(a.nombre))) forma = true;
    if (forma) sinEnvio = 'NV-ADJUNTO-FORMA';
    else if (adjuntosEnLote >= 1) { sinEnvio = 'NV-ADJUNTO-LOTE'; reintentable = true; }
    else adjuntosEnLote += 1;
  }
  const base = { mensajeId, conversacionId, canal, claveRele, sinEnvio, reintentable, ruta: sinEnvio ? 'ninguna' : 'adjunto', tipo };
  if (sinEnvio) return { json: { ...base, adjunto: null, cuerpoAdjunto: null } };
  const medio = {};
  if (a.leyenda !== undefined) medio.caption = a.leyenda;
  if (tipo === 'document' && a.nombre !== undefined) medio.filename = a.nombre;
  if (tipo === 'audio' && a.voz === true) medio.voice = true;
  return { json: {
    ...base,
    adjunto: { mime: a.mime, ext: MIMES[tipo][a.mime], tamano: a.tamano, sha256: a.sha256 },
    cuerpoAdjunto: { messaging_product: 'whatsapp', to, type: tipo, [tipo]: medio },
  }};
}

const salida = [];
for (const m of lista) {
  const p = (m && typeof m === 'object') ? m : {};
  const mensajeId = String(p.mensajeId ?? '');
  const conversacionId = String(p.conversacionId ?? '');
  const texto = typeof p.texto === 'string' ? p.texto : '';
  const to = String(p.to ?? '');
  const canal = String(p.canal ?? '');
  const claveRele = String(p.claveRele ?? '');
  const tipo = p.tipo === undefined ? 'text' : String(p.tipo);
  if (tipo !== 'text') { salida.push(planAdjunto(p, tipo, mensajeId, conversacionId, to, canal, claveRele, texto)); continue; }

  let sinEnvio = '';
  let reintentable = false;
  if (!mensajeId || !conversacionId) sinEnvio = 'NV-RECLAMO';
  else if (canal !== 'rele' && canal !== 'graph') sinEnvio = 'NV-CANAL';
  else if (!/^[0-9]{8,15}$/.test(to)) sinEnvio = 'NV-DESTINO';
  else if (texto.trim() === '' || texto.length > 1000) sinEnvio = 'NV-TEXTO';
  else if (canal === 'rele' && !/^[A-Za-z0-9_.:-]{16,128}$/.test(claveRele)) sinEnvio = 'NV-CLAVE';
  else if (canal === 'rele' && !releListo) { sinEnvio = 'NV-RELE-CONFIG'; reintentable = true; }

  salida.push({ json: {
    mensajeId, conversacionId, canal, claveRele,
    sinEnvio, reintentable,
    // Por donde sigue el Switch: un mensaje con defecto propio NUNCA entra a un nodo de envio.
    ruta: sinEnvio ? 'ninguna' : canal,
    // Mismo cuerpo para el rele y para Graph: el rele reenvia a Graph tal cual.
    cuerpoEnvio: { messaging_product: 'whatsapp', to, type: 'text', text: { body: texto } },
  }});
}
return salida;

// SALIDA DE PERSONA (adjuntos, B3), paso A: de la lectura del adjunto a la subida a Meta.
// Se ejecuta una vez por item (modo "cada item"), tras `Leer adjunto`.
//
// `leerAdjuntoPersona` devuelve los bytes crudos como `application/octet-stream` (no el mime
// real) con `X-NovuChat-Mime`, `X-NovuChat-Sha256` y `Content-Length`. Meta valida el mime de la
// parte (error 131053), asi que aqui se corrige `mimeType`/`fileName` del binario con el mime ya
// validado en `Planificar lote`. El sha256 NO se recalcula aqui (el Code de n8n no tiene
// `crypto` ni `Buffer`): se exige que la cabecera coincida con el del reclamo, y los bytes los
// verifica el servidor (503 si no cuadran).
//
// Cualquier falla sale como `adjuntoSinEnvio` (sin binario, sin leyenda ni nombre): llega a
// `Resultado del envío` como rechazado reintentable. NUNCA incierto: nada se entrego.
const p = $('Planificar lote').item.json;
const r = $input.item.json || {};
const binario = $input.item.binary && $input.item.binary.adjunto;
const a = p.adjunto;
const base = { mensajeId: p.mensajeId, conversacionId: p.conversacionId };
const falla = (c) => ({ json: { ...base, ruta: 'ninguna', adjuntoSinEnvio: c } });

if (r.statusCode === undefined) return falla('NV-ADJUNTO-LECTURA');
const estado = Number(r.statusCode);
if (estado === 404) return falla('NV-ADJUNTO-NO-EXISTE');
if (estado === 409) return falla('NV-ADJUNTO-ESTADO');
// El estado va en el codigo: una credencial rota (401) no se confunde con una falla pasajera (503).
if (estado !== 200) return falla(Number.isInteger(estado) && estado >= 100 && estado <= 599 ? 'NV-ADJUNTO-LECTURA-' + estado : 'NV-ADJUNTO-LECTURA');

const h = (r.headers && typeof r.headers === 'object') ? r.headers : {};
const largo = h['content-length'];
if (!binario || !a || String(h['x-novuchat-mime'] ?? '') !== a.mime || String(h['x-novuchat-sha256'] ?? '') !== a.sha256
  || (largo !== undefined && Number(largo) !== a.tamano)) return falla('NV-ADJUNTO-INTEGRIDAD');

return { json: { ...base, ruta: 'subir', mime: a.mime },
  binary: { adjunto: { ...binario, mimeType: a.mime, fileName: 'adjunto.' + a.ext, fileExtension: a.ext } } };

// SALIDA DE PERSONA (adjuntos, B3), paso B: de la respuesta de `Subir a Meta` al cuerpo del envio.
// Se ejecuta una vez por item (modo "cada item").
//
// Meta responde a `POST /{numero}/media` con { id }. Ese id va en el cuerpo del mensaje
// (`{ type, [type]: { id, caption?, filename?, voice? } }`): NUNCA un `link`. Una subida que no
// dio un id legible no envia nada: sale como `adjuntoSinEnvio` (rechazado reintentable, porque
// no se entrego ningun mensaje), sin binario, leyenda ni nombre.
const p = $('Planificar lote').item.json;
const r = $input.item.json || {};
const base = { mensajeId: p.mensajeId, conversacionId: p.conversacionId };
const falla = (c) => ({ json: { ...base, ruta: 'ninguna', adjuntoSinEnvio: c } });

if (r.statusCode === undefined) return falla('NV-ADJUNTO-SUBIDA');
const estado = Number(r.statusCode);
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) { cuerpo = {}; } }
if (cuerpo === null || typeof cuerpo !== 'object') cuerpo = {};

if (!(estado >= 200 && estado < 300)) {
  const err = (cuerpo.error && typeof cuerpo.error === 'object') ? cuerpo.error : {};
  const codigo = String(err.code ?? '');
  return falla(/^[0-9]{1,10}$/.test(codigo) ? 'NV-ADJUNTO-SUBIDA-' + codigo : 'NV-ADJUNTO-SUBIDA');
}
const id = typeof cuerpo.id === 'string' ? cuerpo.id : '';
if (!/^[A-Za-z0-9_.-]{1,128}$/.test(id)) return falla('NV-ADJUNTO-SUBIDA');

const c = p.cuerpoAdjunto;
return { json: { ...base, ruta: 'enviar', cuerpoEnvio: { ...c, [c.type]: { id, ...c[c.type] } } } };

// SALIDA DE PERSONA, paso 5: de la respuesta del rele o de Graph al resultado
// que se confirma. Se ejecuta una vez por mensaje (modo "cada item").
//
// Reglas (contrato H2 §4; rele B9 y Graph):
//   2xx con id de mensaje ........................ aceptado + idMeta
//   2xx sin id legible ........................... incierto (Meta pudo aceptarlo)
//   error de red, tiempo agotado, 504, WM-3041 ... incierto: NUNCA se reenvia solo
//   rele: lista permitida (WM previos a Graph, WM-3040 con metaCodigo conocido) .. rechazado
//   rele: cualquier otra cosa ..................... incierto
//   Graph 4xx con error.code ...................... rechazado + codigo (+ reintentable)
//   sin envio por defecto propio ................. rechazado + codigo NV-*
//   adjunto: lectura o subida fallida (NV-ADJUNTO-*) .. rechazado reintentable, no entrego nada
// El texto del mensaje nunca sale de este nodo.
//
// Este nodo es el verificador de los envios 'Enviar por el relé', 'Enviar por Graph'
// y 'Enviar adjunto por Graph'
// (ambos con continueRegularOutput, unidos por 'Juntar salidas'): lee el estado HTTP y el
// id de la respuesta de cada uno y decide aceptado / rechazado / incierto.
const p = $('Planificar lote').item.json;
const r = $input.item.json;

const base = { mensajeId: p.mensajeId, conversacionId: p.conversacionId };
const limpio = (v) => String(v ?? '').replace(/[^A-Za-z0-9_.-]/g, '_').slice(0, 40) || 'DESCONOCIDO';
const rechazo = (codigo, reintentable) => ({ json: { ...base, resultado: 'rechazado', codigo: limpio(codigo), reintentable: reintentable === true } });
const incierto = () => ({ json: { ...base, resultado: 'incierto' } });

if (p.sinEnvio) return rechazo(p.sinEnvio, p.reintentable === true);
// Falla del adjunto antes del envio (lectura o subida): rechazado reintentable, nunca incierto.
if (typeof r.adjuntoSinEnvio === 'string' && r.adjuntoSinEnvio !== '') return rechazo(r.adjuntoSinEnvio, true);

// Un error del nodo HTTP (red, tiempo agotado): el mensaje pudo salir.
if (r.error !== undefined && r.statusCode === undefined) return incierto();

// Ni error ni respuesta: el nodo de envio no devolvio nada. El mensaje pudo salir, asi que es
// `incierto` (nunca se reenvia) con una marca para el registro, sin texto ni telefono. Un item
// raro NO tumba la confirmacion de los demas del lote.
const origen = p.canal === 'rele' ? 'Enviar por el relé' : p.ruta === 'adjunto' ? 'Enviar adjunto por Graph' : 'Enviar por Graph';
if (r.statusCode === undefined) return { json: { ...incierto().json, aviso: 'sin-respuesta', origen } };

const estado = Number(r.statusCode);
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) { cuerpo = {}; } }
if (cuerpo === null || typeof cuerpo !== 'object') cuerpo = {};

if (Number(r.statusCode) >= 200 && estado < 300) {
  const primero = Array.isArray(cuerpo.messages) ? cuerpo.messages[0] : undefined;
  const id = primero && typeof primero.id === 'string' ? primero.id : '';
  if (/^[A-Za-z0-9_.=:+/-]{1,120}$/.test(id)) return { json: { ...base, resultado: 'aceptado', idMeta: id } };
  return incierto();
}

const err = (cuerpo.error && typeof cuerpo.error === 'object') ? cuerpo.error : {};
if (p.canal === 'rele') {
  // LISTA PERMITIDA: solo es `rechazado` lo que el rele rechaza ANTES de llamar a Graph
  // (autenticacion, pedido invalido, numero ajeno, falta de clave, tope, saturacion,
  // medio grande, token del cliente) o un rechazo de Meta (WM-3040) con un codigo de
  // Meta conocido. TODO lo demas (WM-3030, 3035, 3036, 3041, 3042, un WM desconocido,
  // un 5xx o un cuerpo ilegible) es `incierto`: el mensaje pudo haber salido.
  const PREVIOS = ['WM-3010', 'WM-3011', 'WM-3012', 'WM-3031', 'WM-3032', 'WM-3033', 'WM-3034', 'WM-3037', 'WM-3038', 'WM-3039'];
  const METAS = ['131047', '131026', '131049', '131051', '131052', '131053', '130429'];
  const wm = typeof err.codigo === 'string' ? err.codigo : '';
  if (wm === 'WM-3040') {
    const meta = String(err.metaCodigo ?? '');
    if (!METAS.includes(meta)) return incierto();
    return rechazo(meta, err.reintentable === true || meta === '130429');
  }
  if (PREVIOS.includes(wm)) return rechazo(wm, err.reintentable === true || wm === 'WM-3037' || wm === 'WM-3038');
  return incierto();
}

// Graph directo: un 5xx o una respuesta sin codigo no dice si salio.
if (!(estado >= 400 && estado < 500) || (typeof err.code !== 'number' && typeof err.code !== 'string')) return incierto();
const codigoMeta = err.code;
return rechazo(codigoMeta, Number(codigoMeta) === 130429 || err.is_transient === true);

// SALIDA DE PERSONA, paso 7: ¿se confirmo todo?, y ¿hay otra vuelta?
//
// Entra la respuesta de `confirmarSalidaPersona` de cada mensaje del lote (el nodo
// HTTP ya las proceso TODAS antes de llegar aqui). Si alguna confirmacion no fue
// un 200 con ok, la ejecucion FALLA con un mensaje que nombra el mensaje y el
// resultado (nunca el texto ni el telefono): una confirmacion perdida es un error
// visible, no un exito falso. El mensaje queda `enviando` y el siguiente reclamo
// lo pasa a `incierto` a los 2 minutos; nunca se reenvia solo.
//
// Sin fallas: sale UN item que vuelve a `Reclamar`. El bucle termina cuando el
// reclamo llega vacio (`Planificar lote` no emite nada) o al llegar al tope de
// vueltas de `Config base` (lo que quede pendiente lo toma el barrido).
const cfg = $('Config base').first().json;
const enviados = $('Resultado del envío').all();
const fallas = [];
$input.all().forEach((it, i) => {
  const r = it.json || {};
  const cuerpo = (r.body && typeof r.body === 'object') ? r.body : {};
  if (Number(r.statusCode) !== 200 || cuerpo.ok !== true) {
    const e = enviados[i] ? enviados[i].json : {};
    fallas.push(`${String(e.mensajeId ?? '?')} (${String(e.resultado ?? '?')}) -> HTTP ${String(r.statusCode ?? 'sin respuesta')}`);
  }
});
if (fallas.length > 0) {
  throw new Error('Salida de persona: no se pudo confirmar ' + fallas.length + ' mensaje(s): ' + fallas.join('; '));
}

const tope = Math.max(1, Math.min(50, Number(cfg.maxVueltas) || 10));
if ($runIndex + 1 >= tope) return [];
return [{ json: { vuelta: $runIndex + 1 } }];
